      de: ["Die maximale Tiefe des Titicacasees beträgt 281 Meter.", "Der See wird von fünf großen Flusssystemen gespeist: Ramis, Coata, Ilave, Huancané und Suchez.", "Etwa 56 % der Seefläche gehören zu Peru, während 44 % auf bolivianischem Staatsgebiet liegen.", "Die Durchschnittstemperatur des Wassers liegt konstant zwischen 10 °C und 14 °C.", "Es gibt mehr als 40 natürliche Inseln im See, darunter die bedeutenden Inseln Taquile und Amantaní.", "Die Uros-Inseln müssen alle 15 bis 20 Jahre teilweise erneuert werden, da das Schilf im Wasser verrottet."],
