    coords: [-73.25, -3.75],
    name: {
      de: "Amazonas",
      hu: "Amazonas",
      ro: "Fluviul Amazon",
      en: "Amazon River"},
    image: "/poi-images/pe-lor-amazon-river-nature-v2.webp",
    description: {
      de: "Der Amazonas entspringt in den peruanischen Anden und ist der wasserreichste Fluss der Erde.",
      hu: "Az Amazonas a perui Andokban ered, és a világ legbővizűbb folyója.",
      ro: "Fluviul Amazon izvorăște din Anzii peruvieni și este fluviul cu cel mai mare debit de apă din lume.",
      en: "The Amazon River originates in the Peruvian Andes and is the largest river in the world by discharge volume.",
      es: "El Amazonas nace en los Andes peruanos y es el río más caudaloso de la Tierra.",
      pt: "O Amazonas nasce nos Andes peruanos e é o rio com maior volume de água da Terra.",
      fr: "L'Amazone prend sa source dans les Andes péruviennes et est le fleuve le plus puissant au monde.",
    },
    descriptionAdvanced: {
      de: "Der Amazonas ist der wasserreichste Fluss der Erde und durchfließt den Norden Südamerikas, wobei er in den peruanischen Anden entspringt. Sein offizieller Beginn in Peru liegt am Zusammenfluss der Flüsse Ucayali und Marañón nahe der Stadt Nauta in der Region Loreto. Mit einem Einzugsgebiet von über sieben Millionen Quadratkilometern transportiert er etwa ein Fünftel des gesamten ins Meer fließenden Süßwassers weltweit. Der Fluss prägt das Leben im peruanischen Regenwald entscheidend, dient als wichtigster Transportweg und bildet die Lebensgrundlage für Millionen von Menschen und unzählige Tierarten. Während der Regenzeit steigt der Wasserspiegel massiv an, was zur Überflutung riesiger Waldflächen führt, die als Várzea bekannt sind. Ökologisch ist der Amazonas ein Hotspot der Biodiversität, in dem Arten wie der Rosa Amazonasdelfin und der Riesenotter beheimatet sind. Trotz seiner immensen Bedeutung ist das Ökosystem durch Abholzung und Bergbauaktivitäten in den Quellregionen zunehmend bedroht.",
      hu: "Az Amazonas a világ legnagyobb vízhozamú folyója, amelynek forrásvidéke a perui Andok gleccsereiben található. Peruban a folyó hivatalosan az Ucayali és a Marañón folyók összefolyásától, Nauta városa közelében veszi fel az Amazonas nevet. A folyó medencéje a Föld legnagyobb trópusi esőerdőjének ad otthont, amely döntő szerepet játszik a globális klímaszabályozásban és a vízkörforgásban. Perui szakaszán a folyó kanyargós vonalvezetése mentén alakultak ki a legfontosabb dzsungelvárosok, mint például Iquitos, amely a világ legnagyobb, közúton megközelíthetetlen városa. Az Amazonas élővilága lenyűgöző: itt él a híres rózsaszín folyami delfin, a fekete kajmán és a világ legnagyobb édesvízi hala, az arapaima. A folyó vízszintje az évszakoktól függően akár 10-15 métert is változhat, meghatározva a helyi közösségek mezőgazdasági és halászati ciklusait. Gazdasági és ökológiai jelentősége miatt a folyó és mellékfolyóinak védelme kritikus fontosságú Dél-Amerika jövője szempontjából.",
      ro: "Fluviul Amazon este cel mai mare curs de apă din lume după volumul de descărcare, izvorând din Anzii peruvieni pentru a traversa continentul sud-american. În Peru, denumirea oficială de Amazon începe la confluența râurilor Ucayali și Marañón, în apropierea localității Nauta din regiunea Loreto. Bazinul său hidrografic acoperă peste 7 milioane de kilometri pătrați, transportând aproximativ 20% din totalul apei dulci care ajunge în oceanele planetei. Fluviul reprezintă principala arteră de transport în jungla peruană, conectând comunități izolate și orașe mari precum Iquitos, care depind în totalitate de navigația fluvială. Biodiversitatea sa este fără egal, adăpostind specii emblematice precum delfinul roz, vidra uriașă și peștele pirarucu. Variațiile sezoniere ale nivelului apei influențează direct ecosistemele de pădure inundabilă, esențiale pentru reproducerea multor specii de pești. Deși imens, Amazonul se confruntă cu provocări majore legate de poluarea cauzată de mineritul ilegal și de defrișările masive din zonele limitrofe.",
      en: "The Amazon River is the world's largest river by discharge volume, originating high in the Peruvian Andes before flowing across South America to the Atlantic Ocean. In Peru, it officially takes its name at the confluence of the Ucayali and Marañón rivers near the town of Nauta in the Loreto region. The river basin covers over seven million square kilometers, carrying approximately 20% of the world's total freshwater runoff into the oceans. It serves as the lifeblood of the Peruvian rainforest, acting as the primary transportation route for isolated communities and major cities like Iquitos, the world's largest city inaccessible by road. The Amazon is a global epicenter of biodiversity, home to unique species such as the pink river dolphin, the black caiman, and the massive arapaima fish. Seasonal flooding causes the river level to rise by up to 15 meters, creating vast flooded forest ecosystems known as várzea. Despite its vastness, the river faces significant environmental threats from deforestation, illegal mining, and climate change affecting its headwaters.",
      es: "El Amazonas es un elemento notable de la geografía y cultura peruana. Nace en los Andes peruanos y es el río más caudaloso de la Tierra. El río más grande del mundo por volumen. Fluye a través de la cuenca del Amazonas. Esta área natural muestra la diversidad paisajística de Perú entre los Andes, la selva amazónica y la costa desértica del Pacífico. Como muchos lugares importantes de Perú, este sitio combina peculiaridades regionales entre el Pacífico, los Andes y el Amazonas con una importancia transversal. De este modo, este lugar contribuye al perfil polifacético de Perú, desde el legado inca y Machu Picchu hasta Lima y la cuenca del Amazonas.",
      pt: "O Amazonas é um elemento notável da geografia e cultura peruana. Nasce nos Andes peruanos e é o rio com maior volume de água da Terra. Maior rio do mundo em volume de água. Flui através da bacia amazônica. Esta área natural mostra a diversidade paisagística do Peru entre os Andes, a floresta amazônica e a costa desértica do Pacífico. Como muitos lugares importantes no Peru, este local combina peculiaridades regionais entre o Pacífico, os Andes e a Amazônia com uma importância abrangente. Desta forma, este local contribui para o perfil multifacetado do Peru, desde a herança Inca e Machu Picchu até Lima e a bacia amazônica.",
      fr: "L'Amazone est un élément remarquable de la géographie et de la culture péruviennes. Il prend sa source dans les Andes péruviennes et est le fleuve le plus riche en eau de la planète. C'est le plus grand fleuve du monde par son débit. Il traverse tout le bassin amazonien. Cette zone naturelle montre la diversité paysagère du Pérou entre les Andes, la forêt amazonienne et la côte désertique du Pacifique. Comme beaucoup de lieux importants au Pérou, ce site combine des particularités régionales entre le Pacifique, les Andes et l'Amazonie avec une importance globale. Ainsi, ce lieu contribue au profil polyvalent du Pérou, de l'héritage inca et du Machu Picchu à Lima et au bassin amazonien.",
    },
