      es: ["Río más caudaloso del mundo.", "Nace en los Andes peruanos.", "Fluye a través de la cuenca del Amazonas.", "Hábitat vital para innumerables especies."],
      pt: ["Rio com maior volume de água do mundo.", "Nasce nos Andes peruanos.", "Flui através da bacia amazônica.", "Habitat importante para inúmeras espécies."],
