    factsAdvanced: {
      de: ["Die Höhe des Ausangate beträgt exakt 6.384 Meter.", "Der Berg ist der fünfthöchste Gipfel in ganz Peru.", "Die Region beherbergt eine der größten Alpaka-Populationen der Welt.", "Die Erstbesteigung durch Europäer gelang im Jahr 1953 durch eine deutsch-österreichische Gruppe.", "Der Vinicunca-Berg liegt in unmittelbarer Nähe und erreicht 5.200 Meter.", "Das Qoyllur Rit'i-Fest findet jährlich Ende Mai oder Anfang Juni statt."],
      hu: ["A csúcs tengerszint feletti magassága 6384 méter.", "A Qoyllur Rit'i fesztivál során a zarándokok 4800 méteres magasságba vonulnak fel.", "A hegy körüli túraútvonal (Ausangate Trek) általában 5-6 napig tart.", "A Sibinacocha-tó a hegység legnagyobb tava, 4860 méter magasan.", "Az Ausangate a Vilcanota-hegység központi eleme.", "A hegy csúcsát először 1953-ban hódították meg."],
      ro: ["Vârful Ausangate are o altitudine de 6.384 de metri.", "Festivalul Qoyllur Rit'i a fost inclus în lista patrimoniului imaterial UNESCO în 2011.", "Pasul Palomani, cel mai înalt punct de pe circuitul de trekking, se află la 5.100 metri.", "Roca dominantă a masivului este granitul acoperit de straturi groase de gheață.", "Masivul este vizibil din orașul Cusco în zilele senine.", "Izvoarele termale de la Pacchanta sunt o atracție populară la baza muntelui."],
      en: ["Ausangate stands at an elevation of 6,384 meters (20,945 feet).", "It is considered the primary 'Apu' of the Cusco region.", "The Ausangate Circuit involves crossing several passes above 5,000 meters.", "The Rainbow Mountain was hidden under snow until climate change revealed its colors in recent decades.", "The mountain was first summited in 1953 by an expedition led by Heinrich Harrer.", "Local communities still use the ancient 'ayllu' social system for land management."],
      es: ["El Ausangate es la quinta montaña más alta de Perú y es considerada una montaña sagrada (Apu) en la mitología andina.", "Se encuentra en el territorio de la República del Perú.", "Inmerso entre la cordillera andina, el desierto costero y la cuenca amazónica."],
      pt: ["O Ausangate é a quinta montanha mais alta do Peru e é considerada uma montanha sagrada (Apu) na mitologia andina.", "Localizado no território da República do Peru.", "Inserido entre a cordilheira andina, o deserto costeiro e a bacia amazónica."],
      fr: ["L'Ausangate est la cinquième plus haute montagne du Pérou et est considérée comme une montagne sacrée (Apu) dans la mythologie andine.", "Situé sur le territoire de la République du Pérou.", "Nichée entre la cordillère des Andes, le désert côtier et le bassin amazonien."],
    },
