      hu: ["Oroszlánfókák és pingvinek otthona.", "Fontos guanóforrás.", "A Paracas Nemzeti Rezervátum része.", "Csak hajóval közelíthető meg."],
      ro: ["Adăpost pentru lei de mare și pinguini.", "Sursă importantă de guano.", "Parte a Rezervației Naționale Paracas.", "Accesibil doar cu barca."],
      en: ["Home to sea lions and penguins.", "Important source of guano.", "Part of the Paracas National Reserve.", "Accessible only by boat."],
      es: ["Hogar de lobos marinos y pingüinos.", "Importante fuente de guano.", "Parte de la Reserva Nacional de Paracas.", "Solo accesible en barco."],
      pt: ["Lar de leões-marinhos e pinguins.", "Fonte importante de guano.", "Parte da Reserva Nacional de Paracas.", "Acessível apenas por barco."],
