      hu: ["Az Amazonas leghosszabb forrásfolyója.", "Hossza több mint 2200 km.", "A Marañónnal egyesülve hozza létre az Amazonast.", "Folyami delfinekben gazdag."],
      ro: ["Cel mai lung izvor al Amazonului.", "Lungime de peste 2.200 km.", "Se unește cu Marañón pentru a forma Amazonul.", "Bogat în delfini de râu."],
      en: ["Longest headwater of the Amazon.", "Length of over 2,200 km.", "Joins the Marañón to form the Amazon.", "Rich in river dolphins."],
      es: ["Afluente más largo del Amazonas.", "Longitud de más de 2.200 km.", "Se une al Marañón para formar el Amazonas.", "Rico en delfines de río."],
