    coords: [-69.3, -15.4],
    name: {
      de: "Suasi-Insel",
      hu: "Suasi-sziget",
      ro: "Insula Suasi",
      en: "Suasi Island"},
    image: "/poi-images/pe-pun-suasi-nature-v2.webp",
    description: {
      de: "Die Suasi-Insel ist die einzige private Insel im Titicaca-See und dient als ökologisches Schutzgebiet.",
      hu: "A Suasi-sziget az egyetlen magánsziget a Titicaca-tóban, és ökológiai rezervátumként szolgál.",
      ro: "Insula Suasi este singura insulă privată din Lacul Titicaca și servește drept rezervație ecologică.",
      en: "Suasi Island is the only private island in Lake Titicaca and serves as an ecological reserve.",
      es: "La isla Suasi es la única isla privada en el lago Titicaca y funciona como una reserva ecológica.",
      pt: "A ilha Suasi é a única ilha privada no Lago Titicaca e funciona como uma reserva ecológica.",
      fr: "L'île Suasi est la seule île privée du lac Titicaca et sert de réserve écologique.",
    },
    descriptionAdvanced: {
      de: "Die Insel Suasi ist eine exklusive, etwa 43 Hektar große Privatinsel im nordöstlichen Teil des Titicacasees, weit entfernt von den üblichen Touristenpfaden. Sie gehört zum Bezirk Moho in der Region Puno und ist bekannt für ihr Engagement im Bereich Ökotourismus und Umweltschutz. Die Insel wurde von der Soziologin Martha Giraldo rehabilitiert, die das Land in ein privates Schutzgebiet für die lokale Flora und Fauna umwandelte. Hier finden sich zahlreiche einheimische Pflanzenarten wie der Queñua-Baum sowie verschiedene Vogelarten und eine Herde von Alpakas und Vikunjas. Das Klima auf der Insel ist aufgrund der Lage im See etwas milder als im Rest des Altiplano, was eine vielfältige Vegetation ermöglicht. Die Gebäude auf der Insel wurden mit traditionellen Materialien wie Adobe und Reetdächern erbaut und nutzen Solarenergie für die Stromversorgung. Suasi bietet eine Atmosphäre der absoluten Stille und Abgeschiedenheit, ideal für Naturbeobachtungen und astronomische Studien aufgrund des extrem klaren Nachthimmels. Von den Hügeln der Insel hat man einen weiten Blick über den Titicacasee, der hier fast wie ein Ozean wirkt.",
      hu: "Suasi-sziget egy exkluzív, körülbelül 43 hektáros magánsziget a Titicaca-tó északkeleti részén, távol a szokásos turistaútvonalaktól. A sziget Puno régió Moho körzetéhez tartozik, és az ökoturizmus, valamint a környezetvédelem iránti elkötelezettségéről ismert. A szigetet Martha Giraldo szociológus rehabilitálta, aki a területet a helyi flóra és fauna magánrezervátumává alakította. Itt számos őshonos növényfaj, például a queñua fa, valamint különféle madárfajok és egy alpaka-, illetve vikunyanyáj található. A sziget klímája a tóban való elhelyezkedése miatt valamivel enyhébb, mint az Altiplano többi részén, ami lehetővé teszi a változatos vegetációt. A szigeten található épületek hagyományos anyagokból, például vályogból és nádtetővel épültek, az áramellátáshoz pedig napenergiát használnak. Suasi a teljes csend és elszigeteltség légkörét kínálja, amely ideális a természet megfigyelésére és a rendkívül tiszta éjszakai égbolt miatti csillagászati tanulmányokra. A sziget dombjairól lenyűgöző kilátás nyílik a Titicaca-tóra, amely itt szinte óceánnak tűnik.",
      ro: "Insula Suasi este o insulă privată exclusivistă de aproximativ 43 de hectare, situată în partea de nord-est a lacului Titicaca, departe de rutele turistice convenționale. Aparține districtului Moho din regiunea Puno și este renumită pentru angajamentul său față de ecoturism și conservarea mediului. Insula a fost reabilitată de sociologul Martha Giraldo, care a transformat terenul într-o rezervație privată pentru flora și fauna locală. Aici se găsesc numeroase specii de plante native, precum arborele Queñua, precum și diverse specii de păsări și o turmă de alpaca și vicuñe. Climatul de pe insulă este ușor mai blând decât în restul regiunii Altiplano datorită efectului termic al lacului, ceea ce permite o vegetație mai bogată. Clădirile de pe insulă sunt construite din materiale tradiționale precum adobe și acoperișuri de stuf, utilizând energia solară pentru electricitate. Suasi oferă o atmosferă de liniște absolută și izolare, fiind ideală pentru observarea naturii și studii astronomice datorită cerului nocturn extrem de senin. De pe dealurile insulei, se poate admira imensitatea lacului Titicaca, care aici seamănă cu un ocean.",
      en: "Suasi Island is an exclusive, approximately 43-hectare private island located in the northeastern part of Lake Titicaca, far from the standard tourist circuits. It belongs to the Moho District in the Puno Region and is renowned for its commitment to ecotourism and environmental conservation. The island was rehabilitated by sociologist Martha Giraldo, who transformed the land into a private sanctuary for local flora and fauna. It is home to numerous native plant species, such as the Queñua tree, as well as various bird species and a resident herd of alpacas and vicuñas. The microclimate on the island is slightly milder than the surrounding Altiplano due to the lake's thermal mass, allowing for diverse vegetation. Structures on the island were built using traditional materials like adobe and thatch, utilizing solar energy for power. Suasi offers an atmosphere of absolute silence and seclusion, making it ideal for nature observation and astronomical studies due to the extremely clear night skies. From the island's hills, visitors can enjoy expansive views over Lake Titicaca, which appears almost like an ocean in this area.",
      es: "La isla Suasi es un elemento notable de la geografía y cultura peruana. Es la única isla de propiedad privada en el Titicaca y se enfoca en el ecoturismo sostenible. Alberga numerosas alpacas y vicuñas en un entorno protegido. Este espacio natural muestra la diversidad paisajística de Perú entre los Andes, la Amazonía y la costa del Pacífico. Como muchos lugares importantes en Perú, este sitio combina exclusividad regional con una importancia global por su conservación. Así, contribuye al perfil polifacético del país, desde el legado inca hasta las iniciativas ecológicas modernas.",
      pt: "A ilha Suasi é um elemento notável da geografia e cultura peruana. É a única ilha de propriedade privada no Titicaca e foca-se no ecoturismo sustentável. Abriga inúmeras alpacas e vicunhas num ambiente protegido. Esta área natural mostra a diversidade paisagística do Peru entre os Andes, a Amazônia e a costa do Pacífico. Como muitos lugares importantes no Peru, este local combina exclusividade regional com uma importância global pela sua conservação. Assim, contribui para o perfil multifacetado do país, desde a herança inca até as iniciativas ecológicas modernas.",
      fr: "L'île Suasi est un élément remarquable de la géographie et de la culture péruviennes. C'est la seule île privée du lac Titicaca, axée sur l'écotourisme durable. Elle abrite de nombreux alpagas et vigognes dans un environnement protégé. Cet espace naturel témoigne de la diversité des paysages du Pérou entre les Andes, l'Amazonie et la côte du Pacifique. Comme de nombreux sites importants au Pérou, ce lieu allie exclusivité régionale et importance globale pour la conservation. Il participe ainsi au profil varié du pays, de l'héritage inca aux initiatives écologiques modernes.",
    },
