      hu: ["Az egyetlen magánsziget a Titicaca-tóban.", "Fókuszban a fenntartható ökoturizmus.", "Számos alpaka és vikunya él itt.", "Energiaellátása 100%-ban napenergiából származik."],
      ro: ["Singura insulă privată din Lacul Titicaca.", "Concentrată pe ecoturism sustenabil.", "Găzduiește multe alpaca și vicuña.", "Energie 100% solară."],
      en: ["Only private island in Lake Titicaca.", "Focuses on sustainable ecotourism.", "Hosts many alpacas and vicuñas.", "100% solar powered."],
      es: ["Única isla privada en el Lago Titicaca.", "Enfoque en ecoturismo sostenible.", "Hogar de muchas alpacas y vicuñas.", "Energía 100% de origen solar."],
      pt: ["Única ilha privada no Lago Titicaca.", "Foco no ecoturismo sustentável.", "Lar de muitas alpacas e vicunhas.", "Energia 100% de origem solar."],
