      hu: ["A Siula Grande hivatalos magassága 6344 méter.", "Az első sikeres megmászást 1936-ban egy német expedíció hajtotta végre.", "Joe Simpson 1985-ben túlélt egy zuhanást a hegy egyik gleccserhasadékába.", "A hegynek van egy kisebb csúcsa is, a Siula Chico (6260 méter).", "A Cordillera Huayhuash a világ egyik legkompaktabb magashegysége.", "Az alaptábor megközelítése általában több napot vesz igénybe."],
